"""Snap span edges to a fixed step for payroll."""

from typing import Iterable, List
from hourglass.parsing import format_span
from hourglass.models import Span


def _check_step(step: int) -> None:
    if step <= 0 or 60 % step:
        raise ValueError(
            f"step must divide an hour evenly: {step}"
        )


def _label(span: Span) -> str:
    hours, rest = divmod(span.minutes, 60)
    return f"{format_span(span)} ({hours}h {rest}m)"


# ---
def round_minute(value: int, step: int) -> int:
    """Nearest multiple of step, halves going up."""
    _check_step(step)
    return (value + step // 2) // step * step


# ---
def round_span(span: Span, step: int) -> Span:
    """Snap both edges. May raise if the span collapses."""
    return Span(
        round_minute(span.start, step),
        round_minute(span.end, step)
    )


# ---
def round_labels(
    spans: Iterable[Span], step: int
) -> List[str]:
    """Labels like 09:00-17:15 (8h 15m) after rounding."""
    _check_step(step)
    return [_label(round_span(s, step)) for s in spans]

