# owner: platform
import unittest
from hourglass.rounding import round_labels, round_minute
from hourglass.models import Span


class RoundMinuteTests(unittest.TestCase):
    def test_rounds_down_below_half(self):
        self.assertEqual(round_minute(67, 15), 60)

    def test_rounds_up_from_half(self):
        self.assertEqual(round_minute(68, 15), 75)
        self.assertEqual(round_minute(38, 15), 45)

    def test_exact_value_is_kept(self):
        self.assertEqual(round_minute(540, 30), 540)


class RoundLabelsTests(unittest.TestCase):
    def test_label_format(self):
        spans = [Span(541, 1032)]
        self.assertEqual(
            round_labels(spans, 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_several_spans_keep_order(self):
        spans = [Span(0, 62), Span(600, 660)]
        self.assertEqual(
            round_labels(spans, 30),
            ["00:00-01:00 (1h 0m)", "10:00-11:00 (1h 0m)"]
        )

    def test_empty_list(self):
        self.assertEqual(round_labels([], 15), [])

    def test_end_of_day(self):
        spans = [Span(1400, 1439)]
        self.assertEqual(
            round_labels(spans, 15),
            ["23:15-24:00 (0h 45m)"]
        )


class BadStepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 90):
            with self.assertRaises(ValueError):
                round_labels([Span(0, 60)], step)

    def test_bad_step_with_no_spans(self):
        with self.assertRaises(ValueError):
            round_labels([], 0)
